function recipeParseLine(line){
  line=String(line||'').trim(); if(!line) return null;
  var m=line.match(/^([0-9]+(?:\.[0-9]+)?)\s+(\S+)\s*(.*)$/);
  if(m){
    var amt=Number(m[1]), tok=m[2], rest=m[3].trim();
    if(/^[A-Za-z%]+$/.test(tok)) return { amount:amt, unit:tok, name:rest||tok };
    return { amount:amt, unit:'', name:tok+(rest?(' '+rest):'') };
  }
  return { amount:null, unit:'', name:line };
}
function recipeParse(text){
  var items=[], lines=String(text||'').split('\n');
  for(var i=0;i<lines.length;i++){ var r=recipeParseLine(lines[i]); if(r) items.push(r); }
  return items;
}
function recipeScale(items, factor){
  factor=Number(factor);
  return items.map(function(it){ return { amount: it.amount==null?null:Math.round(it.amount*factor*100)/100, unit:it.unit, name:it.name }; });
}
function recipeRender(items){
  var html='';
  for(var i=0;i<items.length;i++){
    var it=items[i];
    var amt = it.amount==null? '适量' : (it.amount+ (it.unit?(' '+it.unit):''));
    html+='<div class="item"><span>'+it.name+'</span><span class="n">'+amt+'</span></div>';
  }
  return html;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { recipeParseLine:recipeParseLine, recipeParse:recipeParse, recipeScale:recipeScale, recipeRender:recipeRender };
}
if (typeof window !== 'undefined') {
  window.RecipeForgePure = { recipeParseLine:recipeParseLine, recipeParse:recipeParse, recipeScale:recipeScale, recipeRender:recipeRender };
}
